"""Parse and format ingredient quantities such as '2', '3/4', or '1 1/2'."""

from __future__ import annotations

import re
from fractions import Fraction

QUANTITY = re.compile(r"^(\d+ \d+/\d+|\d+/\d+|\d+(?:\.\d+)?) (.*)$")
VULGAR = {"¼": " 1/4", "½": " 1/2", "¾": " 3/4", "⅓": " 1/3", "⅔": " 2/3"}


def parse_quantity(text: str) -> Fraction:
    """Parse a whole number, a fraction, or a mixed number into a Fraction."""
    return sum((Fraction(part) for part in text.split()), Fraction(0))


def format_quantity(value: Fraction) -> str:
    """Write a quantity the way the recipe cards do: '2', '3/4', or '1 1/2'."""
    whole, rest = divmod(value, 1)
    if rest == 0:
        return str(whole)
    if whole == 0:
        return str(rest)
    return f"{whole} {rest}"


def split_line(line: str) -> tuple[Fraction, str] | None:
    """Split '1 1/2 cup flour' into (Fraction(3, 2), 'cup flour'); None if no quantity."""
    for char, text in VULGAR.items():
        line = line.replace(char, text)
    match = QUANTITY.match(line.lstrip())
    if match is None:
        return None
    return parse_quantity(match.group(1)), match.group(2)

